contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}
    // params: values to try to set after initialization
    function run(uint newMin, address newLog) public payable {
        // Ensure we don't rely on any prior c state; call Initialized to lock configuration
        c.Initialized(); if (__ESBMC_reverted()) return;

        // Try SetMinSum and record whether it reverted
        bool setMinReverted;
        c.SetMinSum(newMin); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            setMinReverted = true;
        } else {
            setMinReverted = false;
        }

        // Try SetLogFile and record whether it reverted
        bool setLogReverted;
        c.SetLogFile(newLog); bool __rev1 = __ESBMC_reverted(); if (__rev1) {
            setLogReverted = true;
        } else {
            setLogReverted = false;
        }

        // General rule: after Initialized was called, both SetMinSum and SetLogFile must revert
        assert(setMinReverted && setLogReverted);
    }

    receive() external payable {}
}

