pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {DEP_BANK} from "../src/DEP_BANK.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    DEP_BANK c;

    function setUp() public {
        c = new DEP_BANK();
    }

    function _run(uint256 newMin, address newLog) internal {
        try c.Initialized() {} catch { return; }
        bool setMinReverted;
        try c.SetMinSum(newMin) {
            setMinReverted = false;
        } catch {
            setMinReverted = true;
        }
        bool setLogReverted;
        try c.SetLogFile(newLog) {
            setLogReverted = false;
        } catch {
            setLogReverted = true;
        }
        assertTrue(setMinReverted && setLogReverted);
    }

    function testFuzz_run(uint256 newMin, address newLog) public {
        vm.assume(newLog.code.length == 0 && uint160(newLog) > 0xffff && newLog != address(this) && newLog != address(c) && newLog != 0x7109709ECfa91a80626fF3989D68f67F5b1DD12D && newLog != 0x000000000000000000636F6e736F6c652e6c6f67 && newLog != 0x4e59b44847b379578588920cA78FbF26c0B4956C && newLog != 0x1804c8AB1F12E6bbf3894d4083f33e07309d1f38);
        _run(newMin, newLog);
    }

    receive() external payable {}
}
